
.tablet {
  width: 100%;
  max-width: 680px;
  margin: 0 auto;
  background: var(--c-surface);
  border: 1px solid var(--c-border-strong);
  border-radius: 14px;
  overflow: hidden;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.08);
  font-size: 13px;
}

.tablet-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 14px;
  background: var(--c-primary);
  color: var(--c-text-inverse);
}

.tablet-title {
  display: flex;
  align-items: center;
  gap: 6px;
  font-weight: 600;
  font-size: 14px;
}

.title-icon {
  font-size: 15px;
}

.tablet-time {
  font-size: 11px;
  opacity: 0.9;
  font-family: var(--font-mono);
}

.tablet-body {
  padding: 12px;
  min-height: 200px;
  max-height: 560px;
  overflow-y: auto;
}

.tab-pane {
  animation: fade-in 0.2s ease;
}

.tab-empty {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 180px;
}

.empty-hint {
  color: var(--c-text-muted);
  font-size: 12px;
}

@keyframes fade-in {
  from { opacity: 0; transform: translateY(4px); }
  to { opacity: 1; transform: translateY(0); }
}
