
.char-panel {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.empty-text {
  text-align: center;
  color: var(--c-text-muted);
  font-size: 12px;
  padding: 24px;
}

.char-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.char-card {
  background: var(--c-surface-elevated);
  border: 1px solid var(--c-border);
  border-radius: 10px;
  padding: 10px 12px;
  border-left: 4px solid var(--c-border-strong);
}

.char-card.conquered {
  border-left-color: var(--c-bar-fill);
}

.char-card.progressing {
  border-left-color: var(--c-accent);
}

.char-card.unconquered {
  border-left-color: var(--c-border-strong);
}

.char-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 6px;
}

.char-name {
  font-size: 14px;
  font-weight: 700;
  color: var(--c-text);
}

.char-stage {
  font-size: 10px;
  padding: 2px 8px;
  border-radius: 10px;
  font-weight: 600;
}

.stage-init {
  background: var(--c-surface-muted);
  color: var(--c-text-muted);
}

.stage-familiar {
  background: var(--c-primary-light);
  color: var(--c-primary);
}

.stage-ambiguous {
  background: var(--c-accent-light);
  color: var(--c-accent);
}

.stage-intimate {
  background: var(--c-bar-bg);
  color: var(--c-bar-fill);
}

.char-status {
  margin-bottom: 8px;
}

.status-badge {
  font-size: 10px;
  padding: 1px 6px;
  border-radius: 8px;
}

.badge-conquered {
  background: var(--c-bar-fill);
  color: white;
}

.badge-progressing {
  background: var(--c-accent);
  color: white;
}

.badge-unconquered {
  background: var(--c-surface-muted);
  color: var(--c-text-muted);
}

.stat-bars {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
