
.info-panel {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.info-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
}

.info-card {
  background: var(--c-surface-elevated);
  border: 1px solid var(--c-border);
  border-radius: 8px;
  padding: 8px 10px;
  text-align: center;
}

.info-label {
  font-size: 10px;
  color: var(--c-text-muted);
  margin-bottom: 4px;
}

.info-value {
  font-size: 13px;
  font-weight: 600;
  color: var(--c-text);
}

.section-title {
  font-size: 12px;
  font-weight: 600;
  color: var(--c-text-muted);
  border-bottom: 1px solid var(--c-border);
  padding-bottom: 4px;
}

.event-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.event-item {
  display: flex;
  gap: 6px;
  font-size: 12px;
  line-height: 1.5;
}

.event-bullet {
  color: var(--c-primary);
  flex-shrink: 0;
}

.event-text {
  color: var(--c-text);
}

.empty-text {
  font-size: 11px;
  color: var(--c-text-muted);
  text-align: center;
  padding: 12px;
}

@media (max-width: 480px) {
  .info-grid {
    grid-template-columns: 1fr;
  }
}
