
.actions-panel {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.empty-text {
  text-align: center;
  color: var(--c-text-muted);
  font-size: 12px;
  padding: 24px;
}

.actions-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.action-card {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  background: var(--c-surface-elevated);
  border: 1px solid var(--c-border);
  border-radius: 10px;
  padding: 10px 12px;
  cursor: pointer;
  transition: all 0.2s;
  text-align: left;
  font-family: var(--font-ui);
  width: 100%;
}

.action-card:hover:not(.disabled) {
  border-color: var(--c-primary);
  background: var(--c-primary-light);
  transform: translateY(-1px);
  box-shadow: 0 2px 8px rgba(74, 144, 217, 0.15);
}

.action-card.sent {
  border-color: var(--c-success);
  background: #ecfdf5;
  cursor: default;
}

.action-card.disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.action-index {
  flex-shrink: 0;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: var(--c-primary);
  color: white;
  font-size: 11px;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
}

.action-card.sent .action-index {
  background: var(--c-success);
}

.action-body {
  flex: 1;
}

.action-title {
  font-size: 13px;
  font-weight: 700;
  color: var(--c-text);
  margin-bottom: 2px;
}

.action-desc {
  font-size: 11px;
  color: var(--c-text-muted);
  line-height: 1.5;
}

.action-sent-mark {
  font-size: 10px;
  color: var(--c-success);
  font-weight: 600;
  flex-shrink: 0;
}

.reset-hint {
  font-size: 10px;
  color: var(--c-text-muted);
  text-align: center;
  padding: 4px;
  cursor: pointer;
}

.reset-hint:hover {
  color: var(--c-primary);
}
