
.notes-panel {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.empty-text {
  text-align: center;
  color: var(--c-text-muted);
  font-size: 12px;
  padding: 24px;
}

.notes-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.note-card {
  background: #fffef5;
  border: 1px solid #f0e6c0;
  border-radius: 8px;
  padding: 10px 12px;
  border-left: 4px solid var(--c-accent);
  box-shadow: 1px 1px 4px rgba(0, 0, 0, 0.04);
}

.note-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 4px;
}

.note-char {
  font-size: 12px;
  font-weight: 700;
  color: var(--c-accent);
}

.note-time {
  font-size: 10px;
  color: var(--c-text-muted);
  font-family: var(--font-mono);
}

.note-content {
  font-size: 12px;
  color: var(--c-text);
  line-height: 1.6;
}
