
.map-panel {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.map-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
}

.map-card {
  background: var(--c-surface-elevated);
  border: 1px solid var(--c-border);
  border-radius: 10px;
  padding: 12px 6px;
  text-align: center;
  cursor: pointer;
  transition: all 0.2s;
  position: relative;
}

.map-card:hover {
  border-color: var(--c-primary);
  background: var(--c-primary-light);
}

.map-card.current {
  border-color: var(--c-primary);
  background: var(--c-primary-light);
  border-width: 2px;
}

.map-icon {
  font-size: 22px;
  margin-bottom: 4px;
}

.map-name {
  font-size: 12px;
  font-weight: 600;
  color: var(--c-text);
}

.map-current-mark {
  position: absolute;
  top: 4px;
  right: 6px;
  color: var(--c-primary);
  font-size: 10px;
}

.map-hint {
  font-size: 11px;
  color: var(--c-text-muted);
  text-align: center;
  padding: 6px;
  background: var(--c-surface-muted);
  border-radius: 6px;
}

.current-loc {
  color: var(--c-primary);
  font-weight: 600;
}

@media (max-width: 480px) {
  .map-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}
