
.stat-bar {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
}

.bar-icon {
  font-size: 12px;
  flex-shrink: 0;
}

.bar-label {
  color: var(--c-text-muted);
  width: 32px;
  flex-shrink: 0;
}

.bar-track {
  flex: 1;
  height: 8px;
  border-radius: 4px;
  overflow: hidden;
  background: var(--c-surface-muted);
}

.track-like {
  background: var(--c-bar-bg);
}

.track-desire {
  background: var(--c-bar-desire-bg);
}

.track-intimacy {
  background: var(--c-bar-intimacy-bg);
}

.track-trust {
  background: var(--c-bar-trust-bg);
}

.bar-fill {
  height: 100%;
  border-radius: 4px;
  transition: width 0.4s ease;
}

.track-like .bar-fill {
  background: var(--c-bar-fill);
}

.track-desire .bar-fill {
  background: var(--c-bar-desire-fill);
}

.track-intimacy .bar-fill {
  background: var(--c-bar-intimacy-fill);
}

.track-trust .bar-fill {
  background: var(--c-bar-trust-fill);
}

.bar-value {
  width: 26px;
  text-align: right;
  font-weight: 600;
  color: var(--c-text);
  font-family: var(--font-mono);
  flex-shrink: 0;
}
