
.tabs {
  display: flex;
  background: var(--c-tab-bg);
  border-bottom: 1px solid var(--c-border);
}

.tab-button {
  flex: 1;
  padding: 9px 4px;
  border: none;
  background: transparent;
  color: var(--c-text-muted);
  font-size: 12px;
  font-family: var(--font-ui);
  cursor: pointer;
  transition: all 0.2s;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  border-right: 1px solid var(--c-border);
}

.tab-button:last-child {
  border-right: none;
}

.tab-button:hover {
  background: var(--c-surface-elevated);
  color: var(--c-primary);
}

.tab-button.active {
  background: var(--c-surface-elevated);
  color: var(--c-tab-active);
  font-weight: 600;
  position: relative;
}

.tab-button.active::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--c-tab-active);
}

.tab-icon {
  font-size: 14px;
}

.tab-label {
  font-size: 11px;
}
